import React, { useEffect, useState } from "react";
import io from "socket.io-client";
import { AuthProvider } from "./Context/AuthContext";
import CanvasBoard from "./components/CanvasBoard";
import ToolBar from "./components/ToolBar";
import UserList from "./components/UserList";
import LoginForm from "./components/LoginForm";

const socket = io("http://localhost:5000");

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);

  useEffect(() => {
    // Listen for user list updates
    socket.on("userList", (userList) => {
      setUsers(userList);
    });

    // Listen for clear board events
    socket.on("clearBoard", () => {
      const canvas = document.querySelector("canvas");
      if (canvas) {
        const ctx = canvas.getContext("2d");
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        // Reset to white background
        ctx.fillStyle = "white";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
    });

    return () => {
      socket.off("userList");
      socket.off("clearBoard");
    };
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
    setIsLoggedIn(true);
    // Notify server about user joining
    socket.emit("userJoined", userData);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUser(null);
    socket.disconnect();
    // Reconnect socket for new session
    socket.connect();
  };

  if (!isLoggedIn) {
    return (
      <AuthProvider>
        <LoginForm onLogin={handleLogin} />
      </AuthProvider>
    );
  }

  return (
    <AuthProvider>
      <div className="h-screen flex flex-col">
        <div className="flex items-center justify-between p-4 bg-blue-600 text-white">
          <h1 className="text-2xl font-bold">Collaborative Whiteboard</h1>
          <div className="flex items-center space-x-4">
            <span>Welcome, {user?.username} ({user?.role})</span>
            <button
              onClick={handleLogout}
              className="px-4 py-2 bg-red-500 text-white rounded hover:bg-red-600"
            >
              Logout
            </button>
          </div>
        </div>
        
        <ToolBar socket={socket} />
        
        <div className="flex-1 flex">
          <div className="flex-1">
            <CanvasBoard socket={socket} />
          </div>
          <UserList users={users} />
        </div>
      </div>
    </AuthProvider>
  );
}

export default App;
